import { z } from 'zod';

/** IDs are cuid-like strings generated by Prisma. Keep them tight to reject junk early. */
export const idSchema = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[a-zA-Z0-9_-]+$/, 'Invalid id');

export const idParamsSchema = z.object({ id: idSchema });
export const videoIdParamsSchema = z.object({ videoId: idSchema });

export const qualitySchema = z.enum(['original', '1080p', '720p', '480p']);

export const paginationSchema = z.object({
  page: z.coerce.number().int().min(1).max(10_000).default(1),
  pageSize: z.coerce.number().int().min(1).max(200).default(48),
});

export const listQuerySchema = paginationSchema.extend({
  genre: z.string().trim().max(64).optional(),
  sort: z.enum(['added', 'title', 'year', 'rating', 'popular']).default('added'),
  year: z.coerce.number().int().min(1870).max(2200).optional(),
});

export const searchQuerySchema = z.object({
  q: z.string().trim().max(120).default(''),
  limit: z.coerce.number().int().min(1).max(100).default(40),
});

export const suggestQuerySchema = z.object({
  q: z.string().trim().min(1).max(120),
});

export const watchProgressSchema = z.object({
  videoId: idSchema,
  positionSec: z
    .number()
    .finite()
    .min(0)
    .max(60 * 60 * 24),
  durationSec: z
    .number()
    .finite()
    .min(0)
    .max(60 * 60 * 24),
  completed: z.boolean().optional(),
  /** Client generated id grouping the progress events of one playback session. */
  sessionId: z.string().max(64).optional(),
  /** Player state; doubles as a heartbeat so the admin sees who is watching. */
  state: z.enum(['playing', 'paused', 'stopped']).optional(),
  mode: z.enum(['direct', 'remux', 'transcode']).optional(),
});

export const capabilitiesSchema = z.object({
  video: z.array(z.string().max(16)).max(16).default([]),
  audio: z.array(z.string().max(16)).max(16).default([]),
  containers: z.array(z.string().max(16)).max(16).default([]),
  hls: z.enum(['native', 'mse', 'none']).default('mse'),
});

export const playbackQuerySchema = z.object({
  quality: qualitySchema.optional(),
  audio: z.coerce.number().int().min(0).max(64).optional(),
  caps: z.string().max(2048).optional(),
});

export const loginSchema = z.object({
  username: z.string().trim().min(1).max(64),
  password: z.string().min(1).max(256),
});

export const setupSchema = z.object({
  username: z
    .string()
    .trim()
    .min(3)
    .max(32)
    .regex(/^[a-zA-Z0-9_.-]+$/, 'Use letters, numbers, dot, dash or underscore'),
  password: z.string().min(10, 'Use at least 10 characters').max(256),
});

export const changePasswordSchema = z.object({
  currentPassword: z.string().min(1).max(256),
  newPassword: z.string().min(10, 'Use at least 10 characters').max(256),
});

export const mediaFolderSchema = z.object({
  path: z.string().trim().min(1).max(1024),
  label: z.string().trim().max(80).optional(),
  kind: z.enum(['movies', 'series', 'mixed']).default('mixed'),
});

export const mediaFolderPatchSchema = z.object({
  label: z.string().trim().max(80).optional(),
  kind: z.enum(['movies', 'series', 'mixed']).optional(),
  enabled: z.boolean().optional(),
});

export const scanRequestSchema = z.object({
  folderId: idSchema.optional(),
  /** Re-probe every file even if size/mtime did not change. */
  full: z.boolean().default(false),
});

const castSchema = z
  .array(
    z.object({
      name: z.string().trim().min(1).max(120),
      role: z.string().trim().max(120).nullish(),
    }),
  )
  .max(100);

const yearSchema = z.number().int().min(1870).max(2200).nullable();

export const moviePatchSchema = z
  .object({
    title: z.string().trim().min(1).max(200),
    year: yearSchema,
    overview: z.string().trim().max(5000).nullable(),
    tagline: z.string().trim().max(300).nullable(),
    genres: z.array(z.string().trim().min(1).max(40)).max(20),
    cast: castSchema,
    director: z.string().trim().max(120).nullable(),
    rating: z.number().min(0).max(10).nullable(),
    contentRating: z.string().trim().max(16).nullable(),
    featured: z.boolean(),
  })
  .partial();

export const seriesPatchSchema = z
  .object({
    title: z.string().trim().min(1).max(200),
    year: yearSchema,
    overview: z.string().trim().max(5000).nullable(),
    genres: z.array(z.string().trim().min(1).max(40)).max(20),
    cast: castSchema,
    rating: z.number().min(0).max(10).nullable(),
    contentRating: z.string().trim().max(16).nullable(),
    featured: z.boolean(),
  })
  .partial();

export const episodePatchSchema = z
  .object({
    title: z.string().trim().min(1).max(200),
    overview: z.string().trim().max(5000).nullable(),
    episodeNumber: z.number().int().min(0).max(5000),
    seasonNumber: z.number().int().min(0).max(500),
  })
  .partial();

export const settingsPatchSchema = z
  .object({
    serverName: z.string().trim().min(1).max(64),
    ffmpegPath: z.string().trim().max(1024),
    ffprobePath: z.string().trim().max(1024),
    defaultQuality: qualitySchema,
    maxStreams: z.number().int().min(1).max(100),
    maxTranscodes: z.number().int().min(0).max(16),
    transcodePreset: z.enum(['ultrafast', 'superfast', 'veryfast', 'faster', 'fast', 'medium']),
    hardwareAcceleration: z.enum(['none', 'nvenc', 'qsv', 'amf']),
    hlsSegmentSeconds: z.number().int().min(2).max(10),
    cacheMaxGb: z.number().min(0.5).max(2000),
    thumbnailsEnabled: z.boolean(),
    mdnsEnabled: z.boolean(),
    mdnsHostname: z
      .string()
      .trim()
      .min(1)
      .max(63)
      .regex(/^[a-z0-9-]+$/, 'Lowercase letters, numbers and dashes only'),
    autoScanIntervalMinutes: z.number().int().min(0).max(10_080),
    cloudSyncEnabled: z.boolean(),
  })
  .partial();

export const profileSchema = z.object({
  name: z.string().trim().min(1).max(32),
  color: z
    .string()
    .regex(/^#[0-9a-fA-F]{6}$/)
    .default('#f97316'),
  isKids: z.boolean().default(false),
});

export const myListSchema = z.object({
  kind: z.enum(['movie', 'series']),
  id: idSchema,
});

export type WatchProgressInput = z.infer<typeof watchProgressSchema>;
export type MediaFolderInput = z.infer<typeof mediaFolderSchema>;
export type MoviePatch = z.infer<typeof moviePatchSchema>;
export type SeriesPatch = z.infer<typeof seriesPatchSchema>;
export type EpisodePatch = z.infer<typeof episodePatchSchema>;
export type SettingsPatch = z.infer<typeof settingsPatchSchema>;
export type ProfileInput = z.infer<typeof profileSchema>;
